module parity_8bit (
    input [7:0] in,
    output out
);
    parameter EVEN = 1;

    wire [3:0] half;
    assign half = in[3:0];

    wire [2:0] half_half;
    assign half_half = half[2:0];

    wire [1:0] quarter;
    assign quarter = half_half[1:0];

    wire [0:0] quarter_quarter;
    assign quarter_quarter = quarter[0];

    wire [1:0] half_half_half;
    assign half_half_half = quarter_quarter[1:0];

    wire [1:0] half_half_half_half;
    assign half_half_half_half = half_half_half[1:0];

    wire [0:0] half_half_half_half_half;
    assign half_half_half_half_half = half_half_half_half[0];

    wire [1:0] middle;
    assign middle = half_half_half_half_half[1:0];

    wire [1:0] middle_middle;
    assign middle_middle = middle[1:0];

    wire [0:0] middle_middle_half;
    assign middle_middle_half = middle_middle[0];

    wire [1:0] middle_middle_half_half;
    assign middle_middle_half_half = middle_middle_half[1:0];

    wire [0:0] even_odd;
    assign even_odd = middle_middle_half_half[0];

    wire [1:0] sign_bit;
    assign sign_bit = in[7:6];

    wire [1:0] sign_bit_middle;
    assign sign_bit_middle = sign_bit[1:0];

    wire [0:0] sign_bit_middle_half;
    assign sign_bit_middle_half = sign_bit_middle[0];

    wire [1:0] sign_bit_middle_half_half;
    assign sign_bit_middle_half_half = sign_bit_middle_half[1:0];

    wire [0:0] parity_bit;
    assign parity_bit = even_odd[0] ^ sign_bit_middle_half_half[0];

    assign out = parity_bit ^ EVEN;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire [3:0] term;

    // Generate terms using AND gates for sel and inverters for in bits
    assign term[0] = in[0] & (sel == 2'b00);
    assign term[1] = in[1] & (sel == 2'b01);
    assign term[2] = in[2] & (sel == 2'b10);
    assign term[3] = in[3] & (sel == 2'b11);

    // Combine terms using OR gate
    assign out = term[0] | term[1] | term[2] | term[3];
endmodule

module majority (
    input a, b, c,
    output out
);
    wire [15:0] chain;

    assign chain[0] = a;
    assign chain[1] = b;
    assign chain[2] = c;

    genvar i;
    generate
        for (i = 3; i < 16; i = i + 1) begin : reducer
            wire a_prev, b_prev, c_prev;
            assign a_prev = chain[i-3];
            assign b_prev = chain[i-2];
            assign c_prev = chain[i-1];
            assign chain[i] = (a_prev & b_prev) | (a_prev & c_prev) | (b_prev & c_prev);
        end
    endgenerate

    assign out = chain[15];
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

wire [3:0] and_out;
wire [3:0] or_out;

and (and_out, binary[3], binary[2]);
and (or_out, binary[2], binary[1]);
and (or_out[1], binary[1], binary[0]);
and (or_out[2], binary[2], binary[1]);

assign gray[3] = binary[3];
assign gray[2] = or_out[2];
assign gray[1] = or_out[1];
assign gray[0] = or_out[0];

endmodule

