module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @* begin
    if (in == 4'b1111)
        code = 2'b00;
    else if (in[0] == 0)
        code = 2'b00;
    else if (in[1] == 0)
        code = 2'b01;
    else if (in[2] == 0)
        code = 2'b10;
    else if (in[3] == 0)
        code = 2'b11;
    else
        code = 2'bxx;
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter s0 = 2'b00,
              s1 = 2'b01,
              s2 = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk, posedge reset) begin
        if (reset)
            current_state <= s0;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            s0: next_state = s1;
            s1: next_state = s2;
            s2: next_state = s0;
            default: next_state = s0;
        endcase
    end

    assign state = current_state;
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg [2:0] state;
    reg [2:0] next_state;

    localparam [2:0] RED    = 3'b100;
    localparam [2:0] YELLOW = 3'b010;
    localparam [2:0] GREEN  = 3'b001;

    // State transition logic
    always @(*) begin
        case (state)
            RED:    next_state = YELLOW;
            YELLOW: next_state = GREEN;
            GREEN:  next_state = RED;
            default:next_state = RED;
        endcase
    end

    // State register with synchronous reset
    always @(posedge clk) begin
        if (reset)
            state <= RED;
        else
            state <= next_state;
    end

    // Output assignment
    assign light = state;

endmodule

