module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // Define state parameters
    localparam [1:0] IDLE = 2'b00,
                     COIN = 2'b01,
                     ITEM = 2'b10;

    reg [1:0] current_state, next_state;

    // State register with synchronous reset
    always @(posedge clk) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                next_state = coin_inserted ? COIN : IDLE;
            end
            COIN: begin
                next_state = item_selected ? ITEM : COIN;
            end
            ITEM: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output current state
    assign state = current_state;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);

wire signed [7:0] in_0_extended = { { {1'b0, in_0[7]}, in_0 }; };
wire signed [15:0] in_0_extended_signed = in_0_extended <<< 8;

wire signed [3:0] in_1_extended = { { {2'b0, in_1[3]}, in_1 }; };
wire signed [15:0] in_1_extended_signed = in_1_extended <<< 12;

assign out = in_0_extended_signed * in_1_extended_signed;

endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    wire signed [15:0] in_1;
    assign in_1 = in_0 >>> 1;
    assign out = ($signed(in_1) > 16'd127) ? 8'd128 : in_1[7:0];
endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    wire signed [8:0] a_ext = a;
    wire signed [8:0] b_ext = b;
    wire signed [8:0] sum = a_ext + b_ext;
    assign out = sum;
endmodule

