module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

    reg [7:0] temp;
    integer i;

    always @(*) begin
        temp = in;
        for (i = 0; i < shift; i = i + 1) begin
            temp = temp << 1;
            temp = temp >> 8;
        end
    end

    assign out = temp;

endmodule

