module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key, can be overridden

    wire [3:0] data_in_lower = data_in[3:0];
    wire [3:0] data_in_upper = data_in[7:4];
    wire [3:0] key_lower = KEY[3:0];
    wire [3:0] key_upper = KEY[3:1]; // Adjusted to match KEY's 4-bit width

    wire [2:0] i_lower = data_in_lower ^ key_lower;
    wire [2:0] i_upper = data_in_upper ^ key_upper;

    wire [3:0] data_out_lower = { ~(i_lower[2:0]), i_lower[3] };
    wire [3:0] data_out_upper = { ~(i_upper[2:0]), i_upper[3] };

    assign data_out = { data_out_upper, data_out_lower };
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    parameter DIVISOR = 2;

    localparam WIDTH = $clog2(DIVISOR);
    reg [WIDTH-1:0] count_reg;

    assign clk_out = (count_reg == DIVISOR - 1) ? 1'b0 : 1'b1;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            count_reg <= 0;
        end else begin
            if (count_reg == DIVISOR - 1) begin
                count_reg <= 0;
            end else begin
                count_reg <= count_reg + 1;
            end
        end
    end
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    // Intermediate wires for bit-wise comparisons
    wire a3_xor_b3, a2_xor_b2, a1_xor_b1, a0_xor_b0;
    wire a3_eq_b3, a2_eq_b2, a1_eq_b1, a0_eq_b0;
    wire term1, term2, term3, term4;
    wire xnor_all, and_eq;

    // Bit-wise XOR for difference detection
    xor xor3(a3_xor_b3, a[3], b[3]);
    xor xor2(a2_xor_b2, a[2], b[2]);
    xor xor1(a1_xor_b1, a[1], b[1]);
    xor xor0(a0_xor_b0, a[0], b[0]);

    // Bit-wise AND for equality terms
    and and3(a3_eq_b3, a[3], b[3]);
    and and2(a2_eq_b2, a[2], b[2]);
    and and1(a1_eq_b1, a[1], b[1]);
    and and0(a0_eq_b0, a[0], b[0]);

    // Combine equality terms with AND gates
    and and_terms(term1, a3_eq_b3, a2_eq_b2);
    and and_terms(term2, term1, a1_eq_b1);
    and and_terms(term3, term2, a0_eq_b0);
    and and_eq(and_eq, term3, xnor_all); // xnor_all combines all XORs

    // Invert signals for gt and lt
    not not_gt(gt, and_eq);
    not not_lt(lt, a3_xor_b3);
    and and_lt_term(lt, lt, a2_xor_b2, a1_xor_b1, a0_xor_b0);

endmodule

