module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

    // Buffer output (directly follows input)
    buf (out0, in);

    // 2-to-4 decoder implementations using basic gates
    wire not_sel0, not_sel1;
    wire term0_1, term0;
    wire term1_1, term1;
    wire term2_1, term2;
    wire term3_1, term3;

    not (not_sel0, sel[0]);
    not (not_sel1, sel[1]);

    and (term0_1, not_sel1, not_sel0);
    and (term0, term0_1, in);

    and (term1_1, not_sel1, sel[0]);
    and (term1, term1_1, in);

    and (term2_1, sel[1], not_sel0);
    and (term2, term2_1, in);

    and (term3_1, sel[1], sel[0]);
    and (term3, term3_1, in);

    // Assign outputs
    assign out1 = term0;
    assign out2 = term1;
    assign out3 = term2;

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    // State register for 8-bit Gray code
    reg [7:0] state;

    // Next state combinational logic
    wire [7:0] next_state;

    // State transition and reset logic
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 8'b00000000; // Reset to S0
        end else begin
            state <= next_state; // Update to next Gray code
        end
    end

    // Convert Gray code to binary (internal conversion)
    assign next_state = (state >> 1) ^ state;

    // Output the current Gray code state
    assign count = state;

endmodule

