always @(*) begin
    casez (in)
        4'b1??? : encoded = 2'b11;
        4'b01?? : encoded = 2'b10;
        4'b001? : encoded = 2'b01;
        4'b0001 : encoded = 2'b00;
        default : encoded = 2'b00;
    endcase

    valid_reg = (in != 4'b0000);
end

assign out = encoded;
assign valid = valid_reg;

endmodule

