assign D[2] = (q_reg[3] & ~q_reg[2] & ~q_reg[1] & ~q_reg[0]) | (~q_reg[3] & q_reg[2] & ~q_reg[1] & ~q_reg[0]);
assign D[3] = (~q_reg[3] & ~q_reg[2] & ~q_reg[1] & ~q_reg[0]);

