module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  reg state; // 0: IDLE, 1: RUN
  reg reason; // 0: CPU_OVERHEATED, 1: NO_MORE_TASKS

  localparam IDLE = 0;
  localparam RUN = 1;

  localparam CPU_OVERHEATED = 0;
  localparam NO_MORE_TASKS = 1;

  always @(posedge arrived) begin
    case (state)
      IDLE: begin
        if (cpu_overheated) begin
          state <= RUN;
          shut_off_computer <= 1;
          reason <= CPU_OVERHEATED;
        end else begin
          shut_off_computer <= 0;
          reason <= NO_MORE_TASKS;
        end
      end
      RUN: begin
        if (!cpu_overheated && !gas_tank_empty) begin
          state <= IDLE;
          shut_off_computer <= 0;
          reason <= NO_MORE_TASKS;
        end else begin
          state <= RUN;
          shut_off_computer <= 1;
          reason <= CPU_OVERHEATED;
        end
      end
      default: begin
        state <= IDLE;
        shut_off_computer <= 0;
        reason <= NO_MORE_TASKS;
      end
    endcase
  end

  always @(*) begin
    keep_driving = (state == RUN);
  end

endmodule

module TopModule (
