    left = 1'b0;
    down = 1'b0;
    right = 1'b0;
    up = 1'b0;

    // Check each bit in the scancode
    for (integer i = 0; i < 16; i = i + 1) begin
      if (scancode[i]) begin
        case (i)
          0: left = 1'b1;
          1: down = 1'b1;
          2: right = 1'b1;
          3: up = 1'b1;
          default: ; // No action for other bits
        endcase
      end
    end
  end

endmodule

