module TopModule (
  input [7:0] code,
  output reg [3:0] out,
  output reg valid
);

  reg [7:0] mem [0:255];
  wire [7:0] reversed_code;

  // Compute reversed_code by reversing bits in code
  assign reversed_code = { code[0], code[1], code[2], code[3],
                           code[4], code[5], code[6], code[7] };

  always @(*) begin
    // Check if all bits in reversed_code are zero (valid condition)
    valid = (reversed_code == 8'h00);
    // Output the first 4 bits of reversed_code when valid
    out = reversed_code[3:0];
  end

  // Task to write reversed_code to memory when valid
  task write_reversed;
    input [7:0] data;
    begin
      mem[data] = data;
    end
  endtask

  // Write to memory when valid is true
  always @(posedge code[7]) begin
    if (valid)
      write_reversed(reversed_code);
  end

endmodule

