module TopModule (
  input clk,
  input a,
  output reg q
);

  localparam STATE_IDLE = 2'b00;
  localparam STATE_PREPARE = 2'b01;
  localparam STATE_WRITE = 2'b10;

  reg [1:0] state, next_state;
  reg [31:0] counter;
  reg [31:0] data_reg;

  // State transition and counter control
  always @(posedge clk) begin
    if (a) begin
      state <= next_state;
      // Reset counter when entering WRITE state, retain otherwise
      if (next_state == STATE_WRITE)
        counter <= 0;
      else
        counter <= counter; // Maintain current value
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      STATE_IDLE: next_state = a ? STATE_PREPARE : STATE_IDLE;
      STATE_PREPARE: next_state = STATE_WRITE;
      STATE_WRITE: next_state = STATE_IDLE;
      default: next_state = STATE_IDLE;
    endcase
  end

  // Data capture and output assignment
  always @(posedge clk) begin
    if (a) begin
      case (state)
        STATE_IDLE:    data_reg <= 32'h0;
        STATE_PREPARE: data_reg <= counter;
        STATE_WRITE:   q <= data_reg[31]; // Output MSB of counter
      endcase
    end
  end

endmodule

