module TopModule (
  input clk,
  input [7:0] d,
  input reset,
  output reg [7:0] q
);

  parameter DEBOUNCE_CYCLES = 16; // Adjust debounce duration as needed

  // Synchronization registers for metastability prevention
  reg [7:0] d_sync1, d_sync2;
  reg reset_sync1, reset_sync2;

  // Debounce counters for each bit
  reg [3:0] counter [7:0];
  reg [7:0] debounced_out;

  // Synchronize input and reset
  always @(posedge clk) begin
    d_sync1 <= d;
    d_sync2 <= d_sync1;
    reset_sync1 <= reset;
    reset_sync2 <= reset_sync1;
  end

  // Debounce logic for each bit
  integer i;
  always @(posedge clk) begin
    if (reset_sync2) begin
      // Reset debounce counters when reset is active
      for (i = 0; i < 8; i = i + 1)
        counter[i] <= 0;
      debounced_out <= 0;
    end else begin
      // Debounce each bit based on synchronized input
      for (i = 0; i < 8; i = i + 1) begin
        if (d_sync2[i] != debounced_out[i]) begin
          if (counter[i] == DEBOUNCE_CYCLES - 1)
            debounced_out[i] <= d_sync2[i];
          else
            counter[i] <= counter[i] + 1;
        end else
          counter[i] <= 0;
      end
    end
  end

  // Update output with debounced value
  always @(posedge clk) begin
    if (!reset_sync2)
      q <= debounced_out;
  end

endmodule

module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [2:0] state, next_state;

  parameter state_get   = 3'b000;
  parameter state_go    = 3'b001;
  parameter state_wait  = 3'b010;
  parameter state_hazard= 3'b011;
  parameter state_error = 3'b100;

  // State register with asynchronous reset
  always @(posedge clk or posedge enable) begin
    if (enable) state <= state_get;
    else state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      state_get: begin
        next_state = (S) ? state_go : state_get;
      end
      state_go: begin
        if (!A && !B && !C)
          next_state = state_wait;
        else if (!A && B && !C)
          next_state = state_hazard;
        else
          next_state = state_error;
      end
      state_wait: begin
        next_state = (A || B || C) ? state_get : state_wait;
      end
      state_hazard: begin
        next_state = (!A && B && !C) ? state_wait : state_error;
      end
      state_error: next_state = state_get;
      default: next_state = state_get;
    endcase
  end

  // Output logic for Z
  always @(*) begin
    Z = (state == state_go) ? 1'b1 : 1'b0;
  end

endmodule

