module TopModule (
  input clk,
  input in,
  input reset,
  output out
);

  wire p0, p1, p2, p3, p4, p5, p6;

  assign p0 = in;

  // NAND gates for p1 to p4
  assign p1 = ~(p0 & p0);
  assign p2 = ~(p1 & p0);
  assign p3 = ~(p2 & p1);
  assign p4 = ~(p3 & p2);

  // AND gate for p5
  assign p5 = p4 & p0;

