module TopModule (
  input a,
  input b,
  output sum,
  output cout
);
  wire [31:0] s;
  assign s[0] = a;
  assign s[1] = b;

  genvar i;
  generate
    for (i = 2; i <= 32; i = i + 1) begin: adder_chain
      wire carry_in;
      if (i == 2)
        assign carry_in = 1'b0;
      else
        assign carry_in = s[i-1];

      assign s[i] = s[i-1] ^ carry_in;
      assign s[i+1] = s[i-1] & carry_in;
    end
  endgenerate

  assign sum = s[32];
  assign cout = s[31];
endmodule

