  localparam UNLOCKED = 1'b1;

  reg state;

  always @(posedge clk) begin
    if (areset) begin
      state <= LOCKED;
      q <= 4'b0;
    end else begin
      case (state)
        LOCKED: begin
          if (load && ena) begin
            state <= UNLOCKED;
            q <= data;
          end
        end
        UNLOCKED: begin
          if (!load || !ena) begin
            state <= LOCKED;
            q <= 4'b0;
          end else begin
            q <= data;
          end
        end
      endcase
    end
  end

endmodule

