    shift_reg = {8'h00, 8'h00, in}; // Initialize with two 8-bit zeros and the 16-bit input

    for (int i = 0; i < 16; i = i + 1) begin
      // Perform shift left and carry binary MSB to 8-bit LSB
      shift_reg = {shift_reg[31:24], shift_reg[23:16], shift_reg[15:0]};

      // Check if current high and low bytes are stable (no further shift possible)
      if ((shift_reg[31:24] == shift_reg[23:16]) && 
          (shift_reg[23:16] == shift_reg[15:0])) begin
        // Break shift and capture final bytes
        out_hi = shift_reg[31:24];
        out_lo = shift_reg[23:16];
        i = 16; // Exit loop after processing
      end
    end
  end

endmodule

