  localparam MAX_COUNT_S1 = 2'd1; // Example: 1 cycle in S1
  localparam MAX_COUNT_S2 = 2'd2; // Example: 2 cycles in S2
  localparam MAX_COUNT_S3 = 2'd3; // Example: 3 cycles in S3

  // State transition and counter logic
  always @(posedge clock) begin
    if (a) begin
      state <= S0;
      count <= 2'd0;
    end else begin
      state <= next_state;
      // Reset counter on state change, increment otherwise
      if (state != next_state)
        count <= 2'd0;
      else if (count < MAX_COUNT_S(state))
        count <= count + 1'd1;
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      S0: next_state = S1; // Transition to S1 and wait
      S1: next_state = (count == MAX_COUNT_S1) ? S2 : S1;
      S2: next_state = (count == MAX_COUNT_S2) ? S3 : S2;
      S3: next_state = (count == MAX_COUNT_S3) ? S0 : S3;
      default: next_state = S0;
    endcase
  end

  // Output logic (Moore: outputs depend only on current state)
  always @(*) begin
    case (state)
      S0: {p, q} = 2'b00;
      S1: {p, q} = 2'b01;
