// Comparison logic using basic gates
wire [2:0] eq_bit;
wire [2:0] gt_bit;
wire [2:0] slt_bit;
wire A_greater_and;
wire A_less_and;

// Generate equality bits (XNOR using NAND and NOT)
nand nand_eq0(eq_bit[0], A[0], B[0]);
nand nand_eq1(eq_bit[1], A[1], B[1]);
nand nand_eq2(eq_bit[2], A[2], B[2]);

// Compute A_equal
nand nand_eq_all(A_equal, eq_bit[0], eq_bit[1], eq_bit[2]);

// Generate greater than bits (A > B)
nand nand_gt0(gt_bit[0], A[0], B[0]);
nand nand_gt1(gt_bit[1], A[1], B[1]);
nand nand_gt2(gt_bit[2], A[2], B[2]);

// Compute A_greater (A > B)
wire and_gt0;
nand nand_and(and_gt0, gt_bit[0], gt_bit[0]);  // GT0 = A[0] > B[0]
nand nand_and_gt(A_greater_and, and_gt0, gt_bit[1]); // A[1] > B[1] and GT0
nand nand_and_gt2(A_greater, A_greater_and, gt_bit[2]); // A[2] > B[2] and previous

// Generate less than bits (A < B)
nand nand_lt0(slt_bit[0], A[0], B[0]);
nand nand_lt1(slt_bit[1], A[1], B[1]);
nand nand_lt2(slt_bit[2], A[2], B[2]);

// Compute A_less (A < B)
wire and_lt0;
nand nand_and(and_lt0, slt_bit[0], slt_bit[0]); // LT0 = A[0] < B[0]
nand nand_and_lt(A_less_and, and_lt0, slt_bit[1]); // A[1] < B[1] and LT0
nand nand_and_lt2(A_less, A_less_and, slt_bit[2]); // A[2] < B[2] and previous

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);
    // A_greater is high when A > B (no loops, direct combinational logic)
    assign A_greater = (A > B);
    // A_equal is high when A == B
    assign A_equal = (A == B);
    // A_less is high when A < B
    assign A_less = (A < B);
endmodule

module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

  reg [3:0] next_out;

  always @(*) begin
    if (!rst_n) begin
      next_out = 4'd0;
    end else if (valid_count) begin
      next_out = out + 4'd1;
    end else begin
      next_out = out;
    end

    if (next_out == 4'd12)
      next_out = 4'd0;
  end

  always @(posedge clk) begin
    out <= next_out;
  end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    localparam [15:0] GEN_POLY = 16'b0000000000000000;
    localparam [15:0] INIT_VALUE = 16'hFFFF;

    wire feedback;
    assign feedback = clk_div ^ GEN_POLY[15];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_div <= INIT_VALUE[NUM_DIV - 1];
        end else begin
            clk_div <= feedback;
        end
    end

    assign clk_div = clk_div ^ GEN_POLY[15];

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

    reg [15:0] instruction;

    always @(posedge clk) begin
        if (rst) begin
            instruction <= 16'b0;
        end else begin
            case (fetch)
                2'b00: instruction[15:8] <= data;
                2'b01: instruction[7:0] <= data;
                default: ; // No change for other fetch values
            endcase
        end
    end

    assign ins = instruction[15:13];
    assign ad1 = instruction[12:8];
    assign ad2 = instruction[7:0];

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      out <= 4'b0000;
    end else begin
      out <= {out[2:0], ~(out[3] ^ out[2])};
    end
  end

endmodule

module right_shifter(clk, q,d);  
    input  clk;  
    input d;  
    output  [7:0] q;  

    wire [7:0] q_reg;  

    assign q = q_reg;  

    always @(posedge clk) begin  
        q_reg <= {d, q_reg[7:1]};  
    end  

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    // Synchronizing registers for clk_a domain
    reg [3:0] data_a_sync;
    reg data_en_sync_a;
    reg data_en_prev_a;

    // Synchronizing registers for clk_b domain
    reg [3:0] data_b_sync;
    reg data_en_sync_b;
    reg data_en_prev_b;

    // Synchronization process for clk_a
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            data_a_sync    <= 4'b0;
            data_en_sync_a <= 1'b0;
            data_en_prev_a <= 1'b0;
        end else begin
            data_a_sync    <= data_in;
            data_en_sync_a <= data_en;
            data_en_prev_a <= data_en_sync_a;
        end
    end

    // Synchronization process for clk_b
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            data_b_sync    <= 4'b0;
            data_en_sync_b <= 1'b0;
            data_en_prev_b <= 1'b0;
        end else begin
            data_b_sync    <= data_a_sync;
            data_en_sync_b <= data_en_sync_a;
            data_en_prev_b <= data_en_sync_b;
        end
    end

    // Edge detection logic
    wire data_en_sync_rise = data_en_sync_b && !data_en_prev_b;

    // Output data based on enable
    always @(*) begin
        dataout = data_en_sync_rise ? data_b_sync : 4'b0;
    end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;
reg [1:0] current_state, next_state;

parameter s0 = 2'b00,
          s1 = 2'b01,
          s2 = 2'b10,
          s3 = 2'b11;

always @(posedge CLK or posedge RST) begin
if (RST)
  current_state <= s0;
else
  current_state <= next_state;
end

always @(*) begin
case (current_state)
  s0: next_state = IN ? s0 : s1;
  s1: next_state = IN ? s2 : s3;
  s2: next_state = IN ? s3 : s0;
  s3: next_state = IN ? s1 : s2;
  default: next_state = s0;
endcase

if (current_state == s3 && !IN)
  MATCH = 1'b1;
else
  MATCH = 1'b0;
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shift_reg;
reg prev_valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 4'b0;
        prev_valid <= 1'b1;
    end else begin
        prev_valid <= shift_reg[3];
        shift_reg <= {shift_reg[2:0], d[0]};
    end
end

assign valid_out = prev_valid & ~shift_reg[3];
assign dout = shift_reg[3];

endmodule

